const dataInput = require('fs').readFileSync(0, 'utf8');
let outBuf = [];
function printf(s) { outBuf.push(s); }
function flush() { process.stdout.write(outBuf.join('')); }

const tokens = dataInput.split(/\s+/).filter(s => s.length > 0);
let tokenIdx = 0;
function nextToken() { return tokens[tokenIdx++]; }

let n, m, mod;
let matrix;

function multiply(one, two) {
    const res = new Array(m);
    for (let i = 0; i < m; i++) {
        res[i] = new Array(m).fill(0n);
    }
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            for (let k = 0; k < m; k++) {
                res[i][j] += (one[i][k] * two[k][j]) % mod;
                res[i][j] %= mod;
            }
        }
    }
    return res;
}

function power(exp, base) {
    if (exp === 1n) {
        return base;
    }

    let res = power(exp / 2n, base);
    res = multiply(res, res);
    if ((exp & 1n) === 1n) {
        res = multiply(res, base);
    }
    return res;
}

function main() {
    mod = 1000000007n;
    n = BigInt(nextToken());
    m = Number(nextToken());
    if (n < BigInt(m)) {
        printf("1");
        flush();
        return;
    }
    if (n === BigInt(m)) {
        printf("2");
        flush();
        return;
    }
    matrix = new Array(m);
    for (let i = 0; i < m; i++) {
        matrix[i] = new Array(m).fill(0n);
    }
    matrix[0][0] = 1n;
    matrix[0][m - 1] = 1n;
    for (let i = 1; i < m; i++) {
        matrix[i][i - 1] = 1n;
    }

    printf(power(n, matrix)[0][0].toString() + "\n");
    flush();
}

main();
